 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await scwin.listSync();
        dts_List.reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41303.trs_Save_OnSuccess" });
