///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name clslogSync
 * @description clslog Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clslogSync = async function() {
    let url;
    url += "&TASK_DD=" + edt_SDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_ClsLog",
        action : "/ELWEaryEnd.do",
        ref : "",
        target : "dts_ClsLog=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    await scwin.clslogSync();
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        //            edt_SDate.text = cGetToday("yyyymmdd");        // 현재날짜

        edt_EDate.hide();
        img_EDate.hide();
        cmb_PeriodTp.hide();
        label_4.hide();
        edt_SDate.setDisabled(false);
        img_SDate.setDisabled(false);
        txb_CHRG_EMP_NM.show("");
        txb_BZ_CLS_TM.show("");
        txb_APPROV_TEAMLEADR_EMP_NM.show("");
        txb_TEAMLEADR_APPROV_TM.show("");
        label_9.show("");
        label_8.show("");
        label_7.show("");
        label_6.show("");
        url += "&OCCR_DD=" + cmb_DateType.getValue(); // 발생일
        url += "&SDATE_O=" + edt_SDate.getValue();
        url += "&EDATE_O=" + edt_SDate.getValue();
        url += "&REPORT_DD=" + cmb_DateType.getValue(); // 제출일
        url += "&SDATE_R=" + edt_SDate.getValue();
        url += "&EDATE_R=" + edt_SDate.getValue();

        // alert(getObjectValue(edt_SDate)+"//"+getObjectValue(edt_EDate)+"//"+getObjectValue(txb_ISU_CD));
        const sbmOptions = {
            id : "sbm_dts_List",
            action : "/ELWEaryEnd.do",
            ref : "",
            target : "dts_List=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        edt_EDate.show("");
        img_EDate.show("");
        cmb_PeriodTp.show("");
        label_4.show("");
        edt_SDate.setDisabled(false);
        img_SDate.setDisabled(false);
        txb_CHRG_EMP_NM.hide();
        txb_BZ_CLS_TM.hide();
        txb_APPROV_TEAMLEADR_EMP_NM.hide();
        txb_TEAMLEADR_APPROV_TM.hide();
        label_9.hide();
        label_8.hide();
        label_7.hide();
        label_6.hide();
        url += "&OCCR_DD=" + cmb_DateType.getValue(); // 발생일
        url += "&SDATE_O=" + edt_SDate.getValue();
        url += "&EDATE_O=" + edt_EDate.getValue();
        url += "&REPORT_DD=" + cmb_DateType.getValue(); // 제출일
        url += "&SDATE_R=" + edt_SDate.getValue();
        url += "&EDATE_R=" + edt_EDate.getValue();

        // alert(getObjectValue(edt_SDate)+"//"+getObjectValue(edt_EDate)+"//"+getObjectValue(txb_ISU_CD));
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/ELWEaryEnd.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
    scwin.buttonSetDis();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let res = window.confirm("확인 저장 하겠습니까?");
    // alert(js_id+"//"+dts_List.NameString(dts_List.RowPosition,'ISU_CD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_DD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_TM'));
    if (res) {
        url += "&USR_ID=" + js_id;
        url += "&ISU_CD=" + dts_List.getCellData(dts_List.getRowPosition(), 'ISU_CD');
        url += "&OCCR_DD=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_DD');
        url += "&OCCR_TM=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_TM');
        const sbmOptions = {
            id : "sbm_dts_parameter",
            action : "/ELWEaryEnd.do",
            ref : "",
            target : "dts_parameter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.listSync();
    }
};

/**
 * @method
 * @name revw
 * @description 담당자 확인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    if (txb_BZ_CLS_TM.getValue() !== "") {
        await $c.win.alert("담당자가 이미 확인하였습니다.");
        return true;
    }
    let res = window.confirm("담당자 확인 저장하시겠습니까?");
    if (res) {
        url += "&USR_ID=" + js_id;
        url += "&TEAMLEADER_YN=" + "N";
        const sbmOptions = {
            id : "sbm_dts_parameter",
            action : "/ELWEaryEnd.do",
            ref : "",
            target : "dts_parameter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.listSync();
    }
};

/**
 * @method
 * @name cls
 * @description 2010.03.09 팀장승인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cls = async function() {
    if (txb_CHRG_EMP_NM.getValue() === "") {
        await $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return true;
    }
    const commit = window.confirm("마감처리 하시겠습니까?");
    if (commit) {
        url += "&USR_ID=" + js_id;
        url += "&TEAMLEADER_YN=" + "Y";
        const sbmOptions = {
            id : "sbm_dts_parameter",
            action : "/ELWEaryEnd.do",
            ref : "",
            target : "dts_parameter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.listSync();
    }
};

