///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name refreshForm
 * @description refresh Form 처리
 * @param {*} interval interval
 * @returns {void}
 * @hidden N
 */
scwin.refreshForm = function(interval) {
    setInterval("fn_list_sync();", interval);
};

/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
};

/**
 * @method
 * @name buttonSetDis
 * @description 담당자 승인, 팀장승인, 재마감처리
 * @returns {void}
 * @hidden N
 */
scwin.buttonSetDis = function() {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate !== edt_SDate.getValue()) {
        btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
        btn_Revw.setDisabled(true);
        btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
        btn_Cls.setDisabled(true);
        return true;
    }

    // 담당자일때
    if (scwin.pJobTitl === "03") {
        if (txb_BZ_CLS_TM.getValue() !== "") // 담당자가 이미 확인처리한 경우

        {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else if (txb_TEAMLEADR_APPROV_TM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
            btn_Revw.setDisabled(false);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        }
    }
    // 팀장일때 - 마감처리
    else {
        // 당번 아이디 들어온 경우 담당자,팀장 확인 처리할수 함
        if (txb_BZ_CLS_TM.getValue() === "" && txb_TEAMLEADR_APPROV_TM.getValue() === "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
            btn_Revw.setDisabled(false);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else if (txb_TEAMLEADR_APPROV_TM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv.gif");
            btn_Cls.setDisabled(false);
        }
    }
};
